def solve(params):
    from fractions import Fraction
    vals=tuple(params['values'])
    n=len(vals)
    max_ending=vals[0]
    max_sofar=vals[0]
    for x in vals[1:]:
        if max_ending + x > x:
            max_ending = max_ending + x
        else:
            max_ending = x
        if max_ending > max_sofar:
            max_sofar = max_ending
    max_linear = max_sofar
    min_ending=vals[0]
    min_sofar=vals[0]
    for x in vals[1:]:
        if min_ending + x < x:
            min_ending = min_ending + x
        else:
            min_ending = x
        if min_ending < min_sofar:
            min_sofar = min_ending
    total=sum(vals)
    if n==1:
        circular_via_complement = vals[0]
    else:
        if min_sofar == total:
            circular_via_complement = max_linear
        else:
            circular_via_complement = total - min_sofar
    ans = max_linear if max_linear > circular_via_complement else circular_via_complement
    steps={'max_non_circular_subarray_sum': max_linear, 'max_circular_via_complement': circular_via_complement}
    return {'answer': ans, 'steps': steps}

