def solve(params):
    vals=params['values']
    n=len(vals)
    best=None
    for start in range(n):
        s=0
        for length in range(1, n):
            idx=(start+length-1)%n
            s+=vals[idx]
            if best is None or s>best:
                best=s
    return int(best)
